'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Loader2, Wallet, Landmark, Shield } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

const UNLOCK_ITEMS = [
  {
    icon: Landmark,
    title: 'Deposit pool — atomic settlement',
    description: 'Deposits collected at booking automatically drawn down on the session charge. Zero manual reconciliation.',
  },
  {
    icon: Wallet,
    title: '70/30 commission splits',
    description: 'Artist and studio shares settle separately on every charge. No end-of-week spreadsheet exports.',
  },
  {
    icon: Shield,
    title: 'Dispute defense pack — auto-bundling',
    description: 'Evidence assembled from booking history, consent forms, and photos. Submitted to Stripe automatically.',
  },
]

export function ConnectOnboardingCallToAction() {
  const [loading, setLoading] = useState(false)

  async function handleEnable() {
    setLoading(true)
    try {
      const res = await fetch('/api/billing/connect/onboard', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'studio' }),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        toast.error(json.error ?? 'Could not start Stripe onboarding. Try again.')
        return
      }

      const json = await res.json() as { url?: string; error?: string }
      if (!json.url) {
        toast.error('No onboarding link returned. Contact support if this persists.')
        return
      }

      window.location.assign(json.url)
    } catch {
      toast.error('Connection error. Check your network and try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-8">
      {/* Editorial serif moment */}
      <div className="space-y-2">
        <h2 className="font-serif italic text-2xl font-normal text-foreground">
          The signature.
        </h2>
        <p className="text-sm leading-6 text-muted-foreground max-w-prose">
          Enable in-studio card payments to charge clients, route artist commissions,
          and file 1099s. Powered by Stripe Connect Express.
        </p>
      </div>

      {/* Feature unlock cards */}
      <div className="grid gap-4 sm:grid-cols-3">
        {UNLOCK_ITEMS.map((item) => (
          <div
            key={item.title}
            className={cn(
              'rounded-xl border border-border/60 bg-card p-5 space-y-3',
              'shadow-[var(--shadow-soft)]',
            )}
          >
            <div className="flex items-center gap-2.5">
              <item.icon className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
              <p className="text-[13px] font-semibold text-foreground leading-snug">
                {item.title}
              </p>
            </div>
            <p className="text-xs leading-5 text-muted-foreground">
              {item.description}
            </p>
          </div>
        ))}
      </div>

      {/* CTA */}
      <div className="flex items-center gap-4">
        <Button
          onClick={handleEnable}
          disabled={loading}
          className="gap-2"
          size="lg"
        >
          {loading ? (
            <>
              <Loader2 className="size-4 animate-spin" aria-hidden="true" />
              Connecting to Stripe
            </>
          ) : (
            'Enable in-studio payments'
          )}
        </Button>
        <p className="text-xs text-muted-foreground">
          You will be redirected to Stripe to verify your business.
        </p>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Loader2, Clock } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import type { ConnectStatusResult } from '@/lib/stripe/connect-status-query'

interface ConnectOnboardingPendingProps {
  status: ConnectStatusResult
}

function formatRequirementsDueBy(iso: string): string {
  try {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    }).format(new Date(iso))
  } catch {
    return iso
  }
}

export function ConnectOnboardingPending({ status }: ConnectOnboardingPendingProps) {
  const [loading, setLoading] = useState(false)

  async function handleContinue() {
    setLoading(true)
    try {
      // refresh-link 302-redirects to a fresh Stripe account link URL
      window.location.assign('/api/billing/connect/refresh-link?type=studio')
    } catch {
      toast.error('Could not refresh onboarding link. Try again.')
      setLoading(false)
    }
  }

  return (
    <div
      className={cn(
        'rounded-xl border border-border/60 bg-card p-6 space-y-5',
        'shadow-[var(--shadow-soft)]',
      )}
    >
      <div className="flex items-start gap-4">
        <div className="mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted">
          <Clock className="size-4 text-muted-foreground" aria-hidden="true" />
        </div>
        <div className="space-y-1.5 min-w-0">
          <h2 className="text-[15px] font-semibold text-foreground leading-snug">
            Onboarding in progress.
          </h2>
          <p className="text-sm leading-6 text-muted-foreground">
            You have started Stripe verification. Resume to finish — Stripe will ask
            for tax documents, a government-issued ID, and a bank account.
          </p>
          {status.requirements_due_by && (
            <p
              className="text-xs tabular-nums text-muted-foreground"
              aria-label={`Verification window closes ${formatRequirementsDueBy(status.requirements_due_by)}`}
            >
              Verification window closes{' '}
              <span className="font-medium text-foreground">
                {formatRequirementsDueBy(status.requirements_due_by)}
              </span>
            </p>
          )}
        </div>
      </div>

      <div className="flex items-center gap-3 pl-12">
        <Button
          onClick={handleContinue}
          disabled={loading}
          size="sm"
          className="gap-2"
        >
          {loading ? (
            <>
              <Loader2 className="size-3.5 animate-spin" aria-hidden="true" />
              Redirecting
            </>
          ) : (
            'Continue verification'
          )}
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Loader2, AlertTriangle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import type { ConnectStatusResult } from '@/lib/stripe/connect-status-query'

interface ConnectOnboardingRestrictedProps {
  status: ConnectStatusResult
}

/**
 * Humanise Stripe's restricted_reason codes into plain-language copy.
 * Stripe returns raw strings — we map the common ones here.
 */
function humaniseRestrictedReason(reason: string | null): string {
  if (!reason) {
    return 'Stripe needs more details to complete verification.'
  }
  const lower = reason.toLowerCase()
  if (lower.includes('verification_document_failure') || lower.includes('document_failure')) {
    return 'ID verification did not go through. Try a clearer photo of a valid, unexpired ID.'
  }
  if (lower.includes('past_due') || lower.includes('requirements.past_due')) {
    return 'Stripe needs your tax documents this week.'
  }
  if (lower.includes('currently_due') || lower.includes('requirements.currently_due')) {
    return 'Stripe is waiting on additional documents to restore full access.'
  }
  if (lower.includes('bank') || lower.includes('external_account')) {
    return 'A verified bank account is still needed. Add one in the Stripe flow.'
  }
  return 'Stripe needs more details to complete verification.'
}

export function ConnectOnboardingRestricted({ status }: ConnectOnboardingRestrictedProps) {
  const [loading, setLoading] = useState(false)

  async function handleProvideDocuments() {
    setLoading(true)
    try {
      window.location.assign('/api/billing/connect/refresh-link?type=studio')
    } catch {
      toast.error('Could not load the document submission link. Try again.')
      setLoading(false)
    }
  }

  const last4 = status.account_id?.slice(0, 12) ?? null

  return (
    <div
      className={cn(
        'rounded-xl border border-border/60 bg-card overflow-hidden',
        'shadow-[var(--shadow-soft)]',
      )}
    >
      {/* Rust left-border — the single Rust accent on this viewport state */}
      <div className="flex">
        <div className="w-0.5 shrink-0 bg-destructive" aria-hidden="true" />
        <div className="flex-1 p-6 space-y-5">
          <div className="flex items-start gap-4">
            <div className="mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-lg bg-destructive/8">
              <AlertTriangle className="size-4 text-destructive" aria-hidden="true" />
            </div>
            <div className="space-y-1.5 min-w-0">
              <h2 className="text-[15px] font-semibold text-foreground leading-snug">
                More information needed.
              </h2>
              <p className="text-sm leading-6 text-muted-foreground">
                {humaniseRestrictedReason(status.restricted_reason)}
              </p>
              {last4 && (
                <p className="mt-2 font-mono text-xs text-muted-foreground tabular-nums">
                  Account ID: acct_{last4}
                </p>
              )}
            </div>
          </div>

          <div className="flex items-center gap-3 pl-12">
            <Button
              onClick={handleProvideDocuments}
              disabled={loading}
              size="sm"
              className="gap-2"
            >
              {loading ? (
                <>
                  <Loader2 className="size-3.5 animate-spin" aria-hidden="true" />
                  Redirecting
                </>
              ) : (
                'Provide documents'
              )}
            </Button>
          </div>
        </div>
      </div>
    </div>
  )
}

