import { useEffect, useRef } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import { toast } from 'sonner'

/**
 * Client component that reads Stripe's return params after onboarding redirect.
 *
 * When Stripe sends the user back to /settings/payments?onboarding=complete&type=studio,
 * this fires a toast and triggers a server-side refresh to pick up the updated DB state.
 *
 * Animation: 150ms ease-out fade-up via Tailwind animate-in (CSS @starting-style approach).
 * We don't confetti on completion — editorial restraint is the brand.
 */
export function ConnectReturnHandler() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const handledRef = useRef(false)

  useEffect(() => {
    if (handledRef.current) return

    const onboarding = searchParams.get('onboarding')
    const type = searchParams.get('type')

    if (onboarding === 'complete' && type === 'studio') {
      handledRef.current = true

      toast('Verification submitted.', {
        description: 'Stripe will email you when your account is ready.',
        duration: 6000,
      })

      // Refresh the Server Component tree to re-fetch DB state
      router.refresh()

      // Clean up URL params without adding a history entry
      const url = new URL(window.location.href)
      url.searchParams.delete('onboarding')
      url.searchParams.delete('type')
      window.history.replaceState(null, '', url.pathname + url.search)
    }
  }, [searchParams, router])

  return null
}

