interface ConnectOnboardingBannerProps {
  studioId: string
}

const DISMISS_KEY_PREFIX = 'inkos:connect-banner-dismissed:'

/**
 * Fetches the studio's Stripe Connect status client-side.
 *
 * We intentionally fetch this on the client so the dashboard page itself
 * remains a fast Server Component. The banner is non-critical UI.
 */
async function fetchConnectStatus(studioId: string): Promise<ConnectStatusResult | null> {
  try {
    const res = await fetch(`/api/billing/connect/status?studioId=${encodeURIComponent(studioId)}`, {
      // 60s cache — fresh enough for UI, cheap enough to not slam the DB
      next: { revalidate: 60 },
    })
    if (!res.ok) return null
    const json = await res.json() as ConnectStatusResult
    return json
  } catch {
    return null
  }
}

function useDismissed(studioId: string) {
  const key = `${DISMISS_KEY_PREFIX}${studioId}`

  function isDismissed(): boolean {
    try {
      return localStorage.getItem(key) === 'true'
    } catch {
      return false
    }
  }

  function dismiss() {
    try {
      localStorage.setItem(key, 'true')
    } catch {
      // localStorage not available (SSR guard, private browsing) — no-op
    }
  }

  return { isDismissed, dismiss }
}

export function ConnectOnboardingBanner({ studioId }: ConnectOnboardingBannerProps) {
  const [status, setStatus] = useState<ConnectStatusResult | null>(null)
  const [dismissed, setDismissed] = useState(false)
  const [loading, setLoading] = useState(true)
  const [continuingKyc, setContinuingKyc] = useState(false)
  const router = useRouter()
  const { isDismissed, dismiss } = useDismissed(studioId)

  useEffect(() => {
    // Check dismiss state first (session-scoped via localStorage, "no account" only)
    if (isDismissed()) {
      setDismissed(true)
      setLoading(false)
      return
    }

    fetchConnectStatus(studioId)
      .then(setStatus)
      .finally(() => setLoading(false))
  }, [studioId]) // eslint-disable-line react-hooks/exhaustive-deps

  // No render while loading or when status is good
  if (loading) return null
  if (!status) return null
  if (status.onboarding_status === 'active') return null

  // "No account" state is dismissible
  if (status.onboarding_status === null && dismissed) return null

  function handleDismiss() {
    dismiss()
    setDismissed(true)
  }

  async function handleContinueKyc() {
    setContinuingKyc(true)
    router.push('/api/billing/connect/refresh-link?type=studio')
  }

  // ── No account ────────────────────────────────────────────────────────────
  if (status.onboarding_status === null) {
    return (
      <div
        className={cn(
          'flex items-center justify-between gap-4 rounded-xl border border-border/60 bg-card px-5 py-3.5',
          'shadow-[var(--shadow-soft)]',
        )}
        role="banner"
        aria-label="Set up in-studio payments"
      >
        <p className="text-sm text-muted-foreground min-w-0">
          Set up in-studio payments to start charging clients.
        </p>
        <div className="flex shrink-0 items-center gap-3">
          <Button variant="ghost" size="sm" asChild>
            <Link href="/settings/payments" className="gap-1.5">
              Get started
              <ArrowRight className="size-3.5" aria-hidden="true" />
            </Link>
          </Button>
          <button
            type="button"
            onClick={handleDismiss}
            className="text-xs text-muted-foreground/60 hover:text-muted-foreground transition-colors"
            aria-label="Dismiss this notice"
          >
            Dismiss
          </button>
        </div>
      </div>
    )
  }

  // ── Pending KYC ───────────────────────────────────────────────────────────
  if (status.onboarding_status === 'pending') {
    return (
      <div
        className={cn(
          'flex items-center justify-between gap-4 rounded-xl border border-border/60 bg-card px-5 py-3.5',
          'shadow-[var(--shadow-soft)]',
        )}
        role="banner"
        aria-label="Stripe verification in progress"
      >
        <p className="text-sm text-foreground font-medium min-w-0">
          Stripe verification in progress.
        </p>
        <Button
          size="sm"
          variant="outline"
          onClick={handleContinueKyc}
          disabled={continuingKyc}
          className="shrink-0 gap-2"
        >
          {continuingKyc ? (
            <>
              <Loader2 className="size-3.5 animate-spin" aria-hidden="true" />
              Redirecting
            </>
          ) : (
            'Continue'
          )}
        </Button>
      </div>
    )
  }

  // ── Restricted ───────────────────────────────────────────────────────────
  if (status.onboarding_status === 'restricted') {
    return (
      <div
        className={cn(
          'flex items-center justify-between gap-4 overflow-hidden rounded-xl border border-border/60 bg-card',
          'shadow-[var(--shadow-soft)]',
        )}
        role="alert"
        aria-label="Stripe needs more documents"
      >
        {/* 2px Rust left border — single Rust accent for this state */}
        <div className="flex flex-1 items-center justify-between gap-4 pl-0 pr-5 py-3.5">
          <div className="w-0.5 shrink-0 self-stretch bg-destructive" aria-hidden="true" />
          <div className="flex flex-1 items-center gap-3 pl-4 min-w-0">
            <AlertTriangle className="size-4 shrink-0 text-destructive" aria-hidden="true" />
            <p className="text-sm text-foreground font-medium min-w-0">
              Stripe needs more documents.
            </p>
          </div>
          <Button
            size="sm"
            onClick={handleContinueKyc}
            disabled={continuingKyc}
            className="shrink-0 gap-2"
          >
            {continuingKyc ? (
              <>
                <Loader2 className="size-3.5 animate-spin" aria-hidden="true" />
                Redirecting
              </>
            ) : (
              'Resolve'
            )}
          </Button>
        </div>
      </div>
    )
  }

  // ── Rejected ──────────────────────────────────────────────────────────────
  if (status.onboarding_status === 'rejected') {
    return (
      <div
        className={cn(
          'flex items-center justify-between gap-4 rounded-xl border border-border/60 bg-muted/40 px-5 py-3.5',
          'shadow-[var(--shadow-soft)]',
        )}
        role="banner"
        aria-label="Stripe account verification failed"
      >
        <p className="text-sm text-muted-foreground min-w-0">
          Stripe could not verify this account.
        </p>
        <Button variant="outline" size="sm" className="shrink-0" asChild>
          <Link href="/settings/payments">Get help</Link>
        </Button>
      </div>
    )
  }

  return null
}

